#!/usr/bin/env python3
"""Chapter 1 from Chapter1.pdf and 01IntroductiontoAlgorithmsComplexity.pdf."""
import json, sqlite3
from pathlib import Path
DB = Path(__file__).with_name('progress.db')
GLOSSARY = {'Algorithm':'A finite, precise sequence of steps for solving a problem.', 'Decomposition':'Breaking a problem into smaller manageable parts.', 'Pseudocode':'An informal, language-independent description of an algorithm.', 'Array':'An indexed collection of elements.', 'Time complexity':'How the number of operations grows with input size.', 'Space complexity':'How memory use grows with input size.'}
LESSONS = [
('Mission 1: Program a robot','Give a robot instructions that actually work.', [('Your first algorithm','<p>A robot needs a {{Algorithm}}: clear steps that solve a problem and eventually stop.</p><div class="example-box">Input: two numbers. Add them. Output the sum.</div>'),('Spot the bug','<p>Instruction: “Make a nice drink.” What is missing?</p><details><summary>Reveal the answer</summary><p>It is ambiguous: specify ingredients, quantities and ordered steps.</p></details>'),('Build a better recipe','<p>Good algorithms have clear instructions, defined inputs and outputs, termination, correctness and feasible steps.</p><p><strong>Challenge:</strong> Write three precise steps for adding two numbers.</p><details><summary>Reveal one solution</summary><p>Read A and B; set S = A + B; output S.</p></details>')]),
('Mission 2: Think like a detective','Break down a problem and spot patterns.', [('Break the mission apart','<p>{{Decomposition}} means splitting a big job into smaller jobs. Planning a trip can become choosing a destination, checking transport, and calculating cost.</p>'),('Find the pattern','<p>Pattern recognition finds similarities that can help solve related problems.</p><p><strong>Challenge:</strong> In 2, 4, 6, 8, what could come next?</p><details><summary>Reveal</summary><p>10: the pattern adds 2 each time.</p></details>'),('Say it in pseudocode','<p>{{Pseudocode}} describes the logic without being tied to a programming language.</p><pre>READ age\nIF age >= 18 THEN\n  PRINT "adult"\nELSE\n  PRINT "under 18"\nEND IF</pre><p>A flowchart can represent the same decision with arrows and a decision diamond.</p>')]),
('Mission 3: Search the snack shelf','Explore arrays and count your moves.', [('Meet the array','<p>An {{Array}} stores items at numbered positions. Indexing starts at 0 in the course example.</p><p><code>[apple, banana, cucumber, dates]</code></p><p><strong>Challenge:</strong> What is at index 2?</p><details><summary>Reveal</summary><p>Cucumber. Count 0, 1, 2.</p></details>'),('Find the dates','<p>Linear search checks items one by one until it finds the target or reaches the end.</p><p><strong>Challenge:</strong> How many checks to find dates in that array?</p><details><summary>Reveal</summary><p>Four checks: apple, banana, cucumber, dates.</p></details>'),('Change the shelf','<p>Reading an array position is direct. Inserting or deleting in the middle may require shifting later items.</p><p><strong>Challenge:</strong> Insert mango at index 1: which original items move?</p><details><summary>Reveal</summary><p>Banana, cucumber and dates shift right.</p></details>')]),
('Mission 4: Beat the clock','Compare solutions carefully.', [('Count the work','<p>{{Time complexity}} describes how work grows as the input grows; {{Space complexity}} describes memory use. Counting steps helps compare approaches, though actual time also depends on implementation and hardware.</p>'),('Same input, same path?','<p>A deterministic algorithm follows a determined next step for a given state. A randomized algorithm can make different choices on different runs.</p><p><strong>Challenge:</strong> Is adding 2 to an input deterministic?</p><details><summary>Reveal</summary><p>Yes: the same input produces the same result by the same defined operation.</p></details>'),('Final challenge','<p>You need to find a name in a list. Describe a linear search, state when it stops, and explain what happens when the name is absent.</p><details><summary>Reveal a solution</summary><p>Check each name from the start; stop when found. If you reach the end without a match, report “not found”. At most n items are checked for n names.</p></details>')])]
QUIZ = [('What makes “do something sensible” a weak algorithm step?',['It is ambiguous','It has too many numbers','It always terminates'],0,'It does not say precisely what to do.'),('What is at index 2 in [apple, banana, cucumber, dates]?',['banana','cucumber','dates'],1,'Indexes start at zero in this example.'),('How many checks to find dates using linear search from the start?',['2','3','4'],2,'Each of the four items is checked.'),('What can happen when inserting into the middle of an array?',['Later items shift','All items disappear','Indexes begin at 1'],0,'Elements after the insertion position may move right.'),('What does decomposition mean?',['Breaking a problem into smaller parts','Checking only the final answer','Running forever'],0,'Smaller tasks are easier to solve separately.'),('What does an algorithm need to do?',['Run forever','Stop after a finite number of steps','Avoid inputs'],1,'Finiteness means it eventually terminates.'),('What does space complexity describe?',['Memory use as input grows','The width of the screen','The output value'],0,'It concerns memory requirements.'),('What does linear search do when the item is absent?',['Stops after checking all items','Returns the first item','Searches forever'],0,'After all items are checked it can report not found.')]
def migrate():
  with sqlite3.connect(DB) as c:
    if c.execute('SELECT 1 FROM courses WHERE id=?',('bcl1313',)).fetchone(): raise RuntimeError('Course already exists; refusing to overwrite')
    c.execute('INSERT INTO courses (id,code,name,description,icon,course_type) VALUES (?,?,?,?,?,?)',('bcl1313','BCL1313','Algorithms and Complexity','Chapter 1: missions, examples and practice','🧩','lesson'))
    for term, definition in GLOSSARY.items(): c.execute('INSERT INTO glossary (course_id,term,definition) VALUES (?,?,?)',('bcl1313',term,definition))
    c.execute('INSERT INTO tutorials (id,course_id,title,short_title,c_idx,sort_order) VALUES (?,?,?,?,?,?)',('bcl1313-ch1','bcl1313','Chapter 1 — Algorithm Adventure','Chapter 1',1,0))
    for i,(title,intro,steps) in enumerate(LESSONS):
      cur=c.execute('INSERT INTO lessons (tutorial_id,number,title,intro,sort_order) VALUES (?,?,?,?,?)',('bcl1313-ch1',i+1,title,intro,i))
      for j,(heading,body) in enumerate(steps): c.execute('INSERT INTO lesson_steps (lesson_id,title,body_html,sort_order) VALUES (?,?,?,?)',(cur.lastrowid,heading,body,j))
      c.execute('INSERT INTO lesson_recaps (lesson_id,text,sort_order) VALUES (?,?,?)',(cur.lastrowid,'Revisit the challenges and explain your reasoning in your own words.',0))
    c.execute('INSERT INTO quiz_chapters (course_id,chapter_idx,name) VALUES (?,?,?)',('bcl1313',1,'Chapter 1 — Algorithm Adventure'))
    for i,(q,options,correct,explanation) in enumerate(QUIZ): c.execute('INSERT INTO quiz_questions (course_id,chapter_idx,question_text,options_json,correct_idx,explanation,sort_order) VALUES (?,?,?,?,?,?,?)',('bcl1313',1,q,json.dumps(options),correct,explanation,i))
if __name__ == '__main__': migrate()
